                type="button"
                onClick={() => setStage('prep')}
                className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-8 py-3.5 rounded-xl flex items-center gap-2 text-base shadow-md hover:shadow-lg transition-all cursor-pointer"
              >
                <span>Comenzar clase</span>
                <ArrowRight className="w-5 h-5" />
              </button>

              <details className="mt-6 text-left max-w-md text-xs text-[#667386] bg-white p-3 rounded-xl border border-[#e2e8f0]">
                <summary className="cursor-pointer font-semibold text-[#1c3257] flex items-center gap-1">
                  <HelpCircle className="w-3.5 h-3.5 text-[#12a1a4]" />
                  ¿Qué ocurrirá al presionar este botón?
                </summary>
                <p className="mt-2 leading-relaxed">
                  Este botón abre únicamente tu preparación privada. La pantalla del estudiante continuará en espera.
                </p>
              </details>
            </div>
          )}

          {/* 2. STAGE: PREP */}
          {session.stage === 'prep' && (
            <div className="animate-fadeIn max-w-2xl mx-auto">
              <h1 className="text-2xl sm:text-3xl font-extrabold text-[#1c3257] mb-5">
                Antes de comenzar
              </h1>

              <div className="flex flex-col items-center space-y-2 mb-6">
                {/* 1. TU OBJETIVO */}
                <div className="w-full bg-white border-l-4 border-l-[#38a169] p-5 rounded-2xl shadow-sm">
                  <strong className="text-[#38a169] text-xs uppercase tracking-wider font-bold block mb-2">
                    TU OBJETIVO
                  </strong>
                  <p className="text-[#2d3748] text-xs sm:text-sm leading-relaxed font-normal">
                    {lessonData.prep.adultObjective}
                  </p>
                </div>

                <div className="flex justify-center text-[#a0aec0] py-0.5">
                  <ArrowDown className="w-3.5 h-3.5" />
                </div>

                {/* 2. RUTA DE HOY */}
                <div className="w-full bg-white border-l-4 border-l-[#dd6b20] p-5 rounded-2xl shadow-sm">
                  <strong className="text-[#dd6b20] text-xs uppercase tracking-wider font-bold block mb-2">
                    RUTA DE HOY
                  </strong>
                  <p className="text-[#2d3748] text-xs sm:text-sm leading-relaxed font-normal">
                    {lessonData.prep.routeToday}
                  </p>
                </div>

                <div className="flex justify-center text-[#a0aec0] py-0.5">
                  <ArrowDown className="w-3.5 h-3.5" />
                </div>

                {/* 3. ¡RECUERDA! */}
                <div className="w-full bg-white border-l-4 border-l-[#d69e2e] p-5 rounded-2xl shadow-sm">
                  <strong className="text-[#b7791f] text-xs uppercase tracking-wider font-bold block mb-2">
                    ¡RECUERDA!
                  </strong>
                  <ol className="list-decimal pl-5 space-y-1.5 text-xs sm:text-sm text-[#2d3748] leading-relaxed">
                    {(lessonData.prep.reminders ?? []).map((reminder, idx) => (
                      <li key={idx} className="pl-1">
                        {reminder}
                      </li>
                    ))}
                  </ol>
                </div>
              </div>

              <div className="flex justify-center pt-2">
                <button
                  type="button"
                  onClick={() => setStage('routeOverview')}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-8 py-3.5 rounded-xl flex items-center gap-2 text-sm shadow-md hover:shadow-lg hover:scale-[1.01] transition-all cursor-pointer"
                >
                  <span>Comenzar con el estudiante</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 3. STAGE: ROUTE OVERVIEW */}
          {session.stage === 'routeOverview' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Nuestra ruta de {lessonData.metadata.subject}</h1>
              <PrivateBox>
                Los títulos orientan la clase. Lee en voz alta solamente lo que aparezca en los recuadros DILE o PREGÚNTALE.
              </PrivateBox>
              <PromptBox label="DILE">
                {lessonData.route.dileIntro}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => setStage('routeToday')}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Conozcamos el primer tema</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 4. STAGE: ROUTE TODAY */}
          {session.stage === 'routeToday' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">La clase de hoy</h1>
              <PromptBox label="DILE">
                {lessonData.route.dileObjective}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => setStage('thermo')}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Comencemos</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 5. STAGE: THERMO */}
          {session.stage === 'thermo' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">
                {lessonData.interactive?.title || 'Conexión inicial'}
              </h1>
              {lessonData.situation.socraticHint && (
                <div className="text-xs text-[#64748b] bg-white p-3 rounded-xl border border-[#dce2e6] mb-4">
                  <strong>AYUDA PEDAGÓGICA:</strong> {lessonData.situation.socraticHint}
                </div>
              )}
              <PromptBox label="DILE">
                {lessonData.situation.dilePrompt}
              </PromptBox>
              <ExpectedAnswerBox>
                {lessonData.situation.expectedAnswer}
              </ExpectedAnswerBox>
              {lessonData.situation.emotionalTip && (
                <div className="text-xs text-[#64748b] bg-white p-2.5 rounded-xl border border-[#dce2e6] mb-4">
                  <strong>CLIMA EMOCIONAL:</strong> {lessonData.situation.emotionalTip}
                </div>
              )}

              <FeedbackBanner feedback={session.feedback} />

              {!session.feedback && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    ¿Qué respondió el estudiante?
                  </p>
                  <div className="grid grid-cols-1 gap-2">
                    {lessonData.situation.options && lessonData.situation.options.length > 0 ? (
                      lessonData.situation.options.map((opt, idx) => (
                        <button
                          key={idx}
                          type="button"
                          onClick={() => {
                            if (opt.kind === 'correct') {
                              handleSuccess(opt.feedbackText);
                            } else {
                              handleSupport(opt.feedbackText);
                            }
                          }}
                          className={`text-left bg-white rounded-xl p-3.5 text-xs font-semibold transition-all shadow-sm cursor-pointer border ${
                            opt.kind === 'correct'
                              ? 'hover:bg-[#eefafb] border-[#b8c4d0] hover:border-[#12a1a4] text-[#1c3257]'
                              : 'hover:bg-[#fff9f0] border-[#f5c49d] text-[#794112]'
                          }`}
                        >
                          {opt.label}
                        </button>
                      ))
                    ) : (
                      <>
                        <button
                          type="button"
                          onClick={() => handleSuccess('¡Correcto! Respuesta esperada comprendida.')}
                          className="text-left bg-white hover:bg-[#eefafb] border border-[#b8c4d0] hover:border-[#12a1a4] rounded-xl p-3.5 text-xs font-semibold text-[#1c3257] transition-all shadow-sm cursor-pointer"
                        >
                          Respondió correctamente: {lessonData.situation.expectedAnswer}
                        </button>
                        <button
                          type="button"
                          onClick={() => handleSupport(lessonData.situation.socraticHint || 'Observa la situación con atención.')}
                          className="text-left bg-white hover:bg-[#fff9f0] border border-[#f5c49d] rounded-xl p-3.5 text-xs font-semibold text-[#794112] transition-all shadow-sm cursor-pointer"
                        >
                          Necesita apoyo
                        </button>
                      </>
                    )}
                  </div>
                </div>
              )}

              {session.feedback?.kind === 'support' && session.attempt === 1 && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    ¿Qué respondió ahora?
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => updateSession({ feedback: { kind: 'success', text: '¡Eso es! Se comprendió la idea con la ayuda.' }, attempt: 2 })}
                      className="text-left bg-white hover:bg-[#eaf4e8] border border-[#badcb8] rounded-xl p-3 text-xs font-bold text-[#255e29] transition-all cursor-pointer"
                    >
                      Respondió tras la pista
                    </button>
                    <button
                      type="button"
                      onClick={() => handleReveal(`La respuesta esperada es: ${lessonData.situation.expectedAnswer}.`)}
                      className="text-left bg-white hover:bg-[#f8f9fa] border border-[#dce2e6] rounded-xl p-3 text-xs font-bold text-[#556376] transition-all cursor-pointer"
                    >
                      Mostrar respuesta esperada
                    </button>
                  </div>
                </div>
              )}

              {(session.feedback?.kind === 'success' || session.feedback?.kind === 'reveal') && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'thermoMeaning', feedback: null, attempt: 0 })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Comprendamos la respuesta</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 6. STAGE: THERMO MEANING */}
          {session.stage === 'thermoMeaning' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">Comprendamos la respuesta</h1>
              <PrivateBox>
                {lessonData.reference.socraticHint}
              </PrivateBox>
              {lessonData.reference.socraticHint && (
                <div className="text-xs text-[#64748b] bg-white p-2.5 rounded-xl border border-[#dce2e6] mb-4">
                  <strong>AYUDA PEDAGÓGICA:</strong> {lessonData.reference.socraticHint}
                </div>
              )}
              <PromptBox label="DILE">
                {lessonData.reference.dilePrompt}
              </PromptBox>
              <PromptBox label="PREGÚNTALE" tone="teal">
                {lessonData.reference.question}
              </PromptBox>
              <ExpectedAnswerBox>
                {lessonData.reference.expectedAnswer}
              </ExpectedAnswerBox>

              <FeedbackBanner feedback={session.feedback} />

              {!session.feedback && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    ¿Cómo respondió?
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => handleSuccess(lessonData.reference.feedbackSuccess)}
                      className="bg-white hover:bg-[#eaf4e8] border border-[#badcb8] rounded-xl p-3.5 text-xs font-bold text-[#255e29] transition-all cursor-pointer"
                    >
                      Respondió correctamente
                    </button>
                    <button
                      type="button"
                      onClick={() => handleSupport(lessonData.reference.feedbackSupport)}
                      className="bg-white hover:bg-[#fff0e4] border border-[#f5c49d] rounded-xl p-3.5 text-xs font-bold text-[#794112] transition-all cursor-pointer"
                    >
                      Necesita apoyo
                    </button>
                  </div>
                </div>
              )}

              {session.feedback && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'hook', feedback: null, hookStarted: false, hookEnded: false })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Seguir con el video</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 7. STAGE: HOOK */}
          {session.stage === 'hook' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">
                {lessonData.hook.titulo || lessonData.metadata.lessonTitle || 'Desafío y Exploración'}
              </h1>
              {!session.hookStarted ? (
                <div>
                  <PromptBox label="DILE">
                    {lessonData.hook.dileIntro}
                  </PromptBox>
                  <div className="mt-6 flex justify-center">
                    <button
                      type="button"
                      onClick={() => startVideo('hook')}
                      className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-8 py-3.5 rounded-xl flex items-center gap-2 text-sm shadow-md hover:shadow-lg transition-all cursor-pointer"
                    >
                      <Play className="w-4 h-4 fill-white" />
                      <span>Reproducir video</span>
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <AdultVideoPlayer
                    src={lessonData.hook.videoSrc}
                    kind="hook"
                    session={session}
                    updateSession={updateSession}
                  />

                  {/* Opcion de avance alternativo para el mentor */}
                  <div className="flex justify-end pt-2">
                    <button
                      type="button"
                      onClick={() =>
                        updateSession({
                          stage: 'conversationIntro',
                          hookEnded: true,
                          video: { ...session.video, playing: false }
                        })
                      }
                      className="text-xs text-slate-500 hover:text-[#EE751C] font-semibold flex items-center gap-1.5 transition-colors cursor-pointer py-1.5 px-3 rounded-lg hover:bg-slate-100"
                      title="Permite continuar a la siguiente etapa si el video ya se vio o no esta disponible"
                    >
                      <span>Continuar a la siguiente etapa</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              )}

              {session.hookEnded && (
                <div className="mt-6 pt-4 border-t border-[#dce2e6]">
                  <PrivateBox>
                    {lessonData.hook.dileAfterVideo}
                  </PrivateBox>
                  <div className="flex justify-between items-center mt-4">
                    <button
                      type="button"
                      onClick={() => startVideo('hook')}
                      className="bg-white hover:bg-[#f1f5f9] text-[#1c3257] border border-[#dce2e6] font-bold px-5 py-2.5 rounded-xl text-xs flex items-center gap-2 transition-all cursor-pointer"
                    >
                      <RotateCcw className="w-3.5 h-3.5" />
                      <span>Ver nuevamente</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => updateSession({ stage: 'conversationIntro', video: { ...session.video, playing: false } })}
                      className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                    >
                      <span>Comprendamos el recorrido</span>
                      <ArrowRight className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* 8. STAGE: CONVERSATION INTRO */}
          {session.stage === 'conversationIntro' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Comprendamos el recorrido</h1>
              <PromptBox label="DILE">
                {lessonData.hook.dileAfterVideo || 'Conversemos sobre lo que acabamos de ver. Voy a hacerte dos preguntas para que juntos comprendamos mejor lo observado.'}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'preQuestions', conversationIndex: 0, feedback: null, attempt: 0 })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Mostrar primera pregunta</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 9. STAGE: PRE QUESTIONS */}
          {session.stage === 'preQuestions' && (
            <div>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold uppercase tracking-wider text-[#12a1a4] bg-[#e6f7f7] px-3 py-1 rounded-full">
                  {currentPreItem.context} · Pregunta {session.conversationIndex + 1} de 2
                </span>
              </div>

              {currentPreItem.teachingBox && (
                <div className="mb-4 bg-blue-50/90 rounded-2xl p-4 border border-blue-200/90 shadow-xs space-y-2.5">
                  <div className="flex items-center gap-2 text-blue-900 font-bold text-xs uppercase tracking-wide">
                    <span className="w-2.5 h-2.5 rounded-full bg-blue-500 animate-pulse"></span>
                    <span>{currentPreItem.teachingBox.title || 'Guía didáctica: Describir vs. Inferir'}</span>
                  </div>
                  <ul className="space-y-1 text-xs text-blue-950 font-medium">
                    {currentPreItem.teachingBox.points.map((pt, i) => (
                      <li key={i} className="flex items-start gap-1.5">
                        <span className="text-blue-600 font-bold">•</span>
                        <span>{pt}</span>
                      </li>
                    ))}
                  </ul>
                  {currentPreItem.teachingBox.modelExample && (
                    <div className="bg-white/90 rounded-xl p-2.5 border border-blue-100 text-xs text-slate-700 leading-relaxed">
                      <span className="font-bold text-blue-900 block mb-0.5">Modelamiento con Robutt:</span>
                      <p className="italic text-slate-800">{currentPreItem.teachingBox.modelExample}</p>
                    </div>
                  )}
                </div>
              )}

              <PromptBox label="PREGÚNTALE">
                {currentPreItem.question}
              </PromptBox>
              <ExpectedAnswerBox>
                {currentPreItem.expected}
              </ExpectedAnswerBox>

              <AdultStudentAnswerAndEvaluationBox
                questionKey={`pre_${session.conversationIndex}`}
                studentAnswer={session.studentTextAnswers?.[`pre_${session.conversationIndex}`]}
                feedback={session.feedback}
                onSuccess={() => handleSuccess(currentPreItem.success)}
                onSupport={() => handleSupport(currentPreItem.support)}
                onReveal={() => handleReveal(currentPreItem.reveal)}
              />

              {(session.feedback?.kind === 'success' || session.feedback?.kind === 'reveal') && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => {
                      if (session.conversationIndex === 0) {
                        updateSession({ conversationIndex: 1, feedback: null, attempt: 0 });
                      } else {
                        updateSession({ stage: 'formalization', feedback: null, attempt: 0, formalStarted: false, formalEnded: false });
                      }
                    }}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Continuar</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 10. STAGE: FORMALIZATION (Video Explicativo) */}
          {session.stage === 'formalization' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">
                {lessonData.formalization.ideaClave || lessonData.metadata.lessonTitle || 'Explicación formal'}
              </h1>
              {!session.formalStarted ? (
                <div>
                  <PromptBox label="DILE">
                    {lessonData.formalization.dileIntro}
                  </PromptBox>
                  {lessonData.formalization.hazInstruction && (
                    <div className="text-xs text-[#64748b] bg-white p-2.5 rounded-xl border border-[#dce2e6] mb-4">
                      <strong>AYUDA PEDAGÓGICA:</strong> {lessonData.formalization.hazInstruction}
                    </div>
                  )}
                  <div className="mt-6 flex justify-center">
                    <button
                      type="button"
                      onClick={() => startVideo('formal')}
                      className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-8 py-3.5 rounded-xl flex items-center gap-2 text-sm shadow-md hover:shadow-lg transition-all cursor-pointer"
                    >
                      <Play className="w-4 h-4 fill-white" />
                      <span>Reproducir video explicativo</span>
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <AdultVideoPlayer
                    src={lessonData.formalization.videoSrc ?? ''}
                    kind="formal"
                    session={session}
                    updateSession={updateSession}
                  />

                  {/* Opcion de avance alternativo para el mentor */}
                  <div className="flex justify-end pt-2">
                    <button
                      type="button"
                      onClick={() =>
                        updateSession({
                          stage: 'postIntro',
                          formalEnded: true,
                          video: { ...session.video, playing: false }
                        })
                      }
                      className="text-xs text-slate-500 hover:text-[#EE751C] font-semibold flex items-center gap-1.5 transition-colors cursor-pointer py-1.5 px-3 rounded-lg hover:bg-slate-100"
                      title="Permite avanzar a la comprobacion de aprendizaje si el video ya se vio o no esta disponible"
                    >
                      <span>Continuar a la siguiente etapa</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              )}

              {session.formalEnded && (
                <div className="mt-6 pt-4 border-t border-[#dce2e6] flex justify-between items-center">
                  <button
                    type="button"
                    onClick={() => startVideo('formal')}
                    className="bg-white hover:bg-[#f1f5f9] text-[#1c3257] border border-[#dce2e6] font-bold px-5 py-2.5 rounded-xl text-xs flex items-center gap-2 transition-all cursor-pointer"
                  >
                    <RotateCcw className="w-3.5 h-3.5" />
                    <span>Ver nuevamente</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'postIntro', video: { ...session.video, playing: false } })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Continuar</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 11. STAGE: POST INTRO */}
          {session.stage === 'postIntro' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">
                Comprobemos lo aprendido
              </h1>
              <PromptBox label="DILE">
                {(lessonData.formalization as any)?.postDileIntro ||
                  `Comprobemos lo que acabamos de revisar sobre ${lessonData.metadata.lessonTitle || 'la clase'}. Te haré dos preguntas para verificar las ideas centrales.`}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'postQuestions', postIndex: 0, feedback: null, attempt: 0 })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Mostrar primera pregunta</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 12. STAGE: POST QUESTIONS */}
          {session.stage === 'postQuestions' && (
            <div>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold uppercase tracking-wider text-[#12a1a4] bg-[#e6f7f7] px-3 py-1 rounded-full">
                  {currentPostItem.context} · Pregunta {session.postIndex + 1} de 2
                </span>
              </div>

              {currentPostItem.teachingBox && (
                <div className="mb-4 bg-blue-50/90 rounded-2xl p-4 border border-blue-200/90 shadow-xs space-y-2.5">
                  <div className="flex items-center gap-2 text-blue-900 font-bold text-xs uppercase tracking-wide">
                    <span className="w-2.5 h-2.5 rounded-full bg-blue-500 animate-pulse"></span>
                    <span>{currentPostItem.teachingBox.title || 'Guía didáctica: Describir vs. Inferir'}</span>
                  </div>
                  <ul className="space-y-1 text-xs text-blue-950 font-medium">
                    {currentPostItem.teachingBox.points.map((pt, i) => (
                      <li key={i} className="flex items-start gap-1.5">
                        <span className="text-blue-600 font-bold">•</span>
                        <span>{pt}</span>
                      </li>
                    ))}
                  </ul>
                  {currentPostItem.teachingBox.modelExample && (
                    <div className="bg-white/90 rounded-xl p-2.5 border border-blue-100 text-xs text-slate-700 leading-relaxed">
                      <span className="font-bold text-blue-900 block mb-0.5">Modelamiento con Robutt:</span>
                      <p className="italic text-slate-800">{currentPostItem.teachingBox.modelExample}</p>
                    </div>
                  )}
                </div>
              )}

              <PromptBox label="PREGÚNTALE">
                {currentPostItem.question}
              </PromptBox>
              <ExpectedAnswerBox>
                {currentPostItem.expected}
              </ExpectedAnswerBox>

              <AdultStudentAnswerAndEvaluationBox
                questionKey={`post_${session.postIndex}`}
                studentAnswer={session.studentTextAnswers?.[`post_${session.postIndex}`]}
                feedback={session.feedback}
                onSuccess={() => handleSuccess(currentPostItem.success)}
                onSupport={() => handleSupport(currentPostItem.support)}
                onReveal={() => handleReveal(currentPostItem.reveal)}
              />

              {(session.feedback?.kind === 'success' || session.feedback?.kind === 'reveal') && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => {
                      if (session.postIndex === 0) {
                        updateSession({ postIndex: 1, feedback: null, attempt: 0 });
                      } else {
                        updateSession({ stage: 'summary', feedback: null });
                      }
                    }}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Continuar</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 13. STAGE: SUMMARY */}
          {session.stage === 'summary' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">En resumen</h1>
              <PromptBox label="DILE">
                {lessonData.summaryText || lessonData.summaryIdeas?.[0]?.[1] || 'En este recorrido identificamos las ideas principales de la clase. Revisemos los conceptos clave antes de continuar.'}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'practiceIntro', practiceIndex: 0, feedback: null })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Practiquemos juntos</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 14. STAGE: PRACTICE INTRO */}
          {session.stage === 'practiceIntro' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Practiquemos juntos</h1>
              <PromptBox label="DILE">
                {session.practiceIndex === 0
                  ? ((lessonData as any).practiceDileIntro ||
                    `Ahora apliquemos lo que hemos aprendido sobre ${lessonData.metadata.lessonTitle || 'la clase'} en situaciones prácticas. Resolveremos cada caso paso a paso: primero ${currentPracticeItem?.context || 'el primer caso'}.`)
                  : `Pasemos al caso ${session.practiceIndex + 1} de ${lessonData.practice.length || 2}: ${currentPracticeItem.context || 'siguiente caso'}.`}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'practice', feedback: null, attempt: 0 })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>
                    Mostrar {session.practiceIndex === 0 ? 'primer' : 'segundo'} caso ({session.practiceIndex + 1} de {lessonData.practice.length || 2})
                  </span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 15. STAGE: PRACTICE */}
          {session.stage === 'practice' && (
            <div>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-bold uppercase tracking-wider text-[#12a1a4] bg-[#e6f7f7] px-3 py-1 rounded-full">
                  {currentPracticeItem.context} · Caso {session.practiceIndex + 1} de {lessonData.practice.length || 2}
                </span>
              </div>
              <PromptBox label="PREGÚNTALE">
                {currentPracticeItem.question}
              </PromptBox>
              <ExpectedAnswerBox>
                {currentPracticeItem.expected}
              </ExpectedAnswerBox>

              <AdultStudentAnswerAndEvaluationBox
                questionKey={`practice_${session.practiceIndex}`}
                studentAnswer={session.studentTextAnswers?.[`practice_${session.practiceIndex}`]}
                feedback={session.feedback}
                onSuccess={() => handleSuccess(currentPracticeItem.success)}
                onSupport={() => handleSupport(currentPracticeItem.support)}
                onReveal={() => handleReveal(currentPracticeItem.reveal)}
              />

              {(session.feedback?.kind === 'success' || session.feedback?.kind === 'reveal') && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => {
                      const totalPractice = lessonData.practice?.length || 2;
                      if (session.practiceIndex < totalPractice - 1) {
                        updateSession({
                          stage: 'practiceIntro',
                          practiceIndex: session.practiceIndex + 1,
                          feedback: null,
                          attempt: 0
                        });
                      } else {
                        if (lessonData.reasoning) {
                          updateSession({ stage: 'reasoningIntro', feedback: null, attempt: 0 });
                        } else {
                          updateSession({ stage: 'practiceSummary', summaryIdea: 0, feedback: null });
                        }
                      }
                    }}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Continuar</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 16. STAGE: REASONING INTRO */}
          {session.stage === 'reasoningIntro' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">
                {lessonData.reasoning?.title || 'Comparemos dos situaciones'}
              </h1>
              <PromptBox label="DILE">
                {lessonData.reasoning?.dileIntro || 'Antes de resumir, comparemos dos situaciones. No necesitas repetir una frase exacta: lo importante es que expliques la idea con tus propias palabras.'}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'reasoning', feedback: null, attempt: 0, reasoningIndependent: false })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Mostrar comparación</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 17. STAGE: REASONING */}
          {session.stage === 'reasoning' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">
                {lessonData.reasoning?.title || 'Comparemos dos situaciones'}
              </h1>
              <PromptBox label="PREGÚNTALE">
                {lessonData.reasoning?.question || 'Al comparar dos situaciones de la clase de hoy, ¿qué diferencias y semejanzas observas? Explica tu respuesta.'}
              </PromptBox>
              <ExpectedAnswerBox>
                {lessonData.reasoning?.expectedAnswer || 'Identificar cómo cambian los datos y qué significado tienen en cada contexto.'}
              </ExpectedAnswerBox>

              <FeedbackBanner feedback={session.feedback} />

              {!session.feedback && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    ¿Cómo explicó su respuesta?
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'success', text: lessonData.reasoning?.successFeedback || '¡Excelente razonamiento! Reconociste la idea central con claridad.' },
                        reasoningIndependent: true
                      })}
                      className="bg-white hover:bg-[#eaf4e8] border border-[#badcb8] rounded-xl p-3 text-xs font-bold text-[#255e29] transition-all cursor-pointer"
                    >
                      Explicó ambas ideas
                    </button>
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'support', text: lessonData.reasoning?.supportFeedback || 'Pensemos en cada situación por separado y observa qué elementos las distinguen.' },
                        attempt: 1,
                        reasoningIndependent: false
                      })}
                      className="bg-white hover:bg-[#fff0e4] border border-[#f5c49d] rounded-xl p-3 text-xs font-bold text-[#794112] transition-all cursor-pointer"
                    >
                      Explicó solo una idea
                    </button>
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'support', text: lessonData.reasoning?.supportFeedback || 'Pensemos en cada situación por separado y observa qué elementos las distinguen.' },
                        attempt: 1,
                        reasoningIndependent: false
                      })}
                      className="bg-white hover:bg-[#fff0e4] border border-[#f5c49d] rounded-xl p-3 text-xs font-bold text-[#794112] transition-all cursor-pointer"
                    >
                      Necesita apoyo
                    </button>
                  </div>
                </div>
              )}

              {session.feedback?.kind === 'support' && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    Después de la pista…
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'success', text: lessonData.reasoning?.successFeedback || '¡Excelente! Ahora explicó la idea con precisión.' },
                        reasoningIndependent: false
                      })}
                      className="bg-white hover:bg-[#eaf4e8] border border-[#badcb8] rounded-xl p-3.5 text-xs font-bold text-[#255e29] transition-all cursor-pointer"
                    >
                      Ahora explicó ambas ideas
                    </button>
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'reveal', text: lessonData.reasoning?.revealText || (lessonData.reasoning?.expectedAnswer ? `La explicación esperada es: ${lessonData.reasoning.expectedAnswer}` : 'El análisis demuestra la importancia de considerar el contexto.') },
                        attempt: 2,
                        reasoningIndependent: false
                      })}
                      className="bg-white hover:bg-[#f8f9fa] border border-[#dce2e6] rounded-xl p-3.5 text-xs font-bold text-[#556376] transition-all cursor-pointer"
                    >
                      Todavía necesita apoyo
                    </button>
                  </div>
                </div>
              )}

              {(session.feedback?.kind === 'success' || session.feedback?.kind === 'reveal') && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => updateSession({
                      stage: session.reasoningIndependent ? 'challenge' : 'strategy',
                      feedback: null,
                      attempt: 0
                    })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>{session.reasoningIndependent ? 'Ir al desafío breve' : 'Ver estrategia para pensar'}</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 18. STAGE: CHALLENGE */}
          {session.stage === 'challenge' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-2">
                {lessonData.challenge?.title || 'Desafío breve'}
              </h1>
              <PrivateBox>
                Esta profundización aparece porque resolvió la comparación anterior sin apoyo. Valora su explicación aunque utilice palabras diferentes.
              </PrivateBox>
              <PromptBox label="PREGÚNTALE">
                {lessonData.challenge?.question || 'En esta situación de desafío, ¿cómo explicarías la relación entre los datos y el procedimiento? Explica tu respuesta.'}
              </PromptBox>
              <ExpectedAnswerBox>
                {lessonData.challenge?.expectedAnswer || 'Explicar con precisión el procedimiento y fundamentar la respuesta.'}
              </ExpectedAnswerBox>

              <FeedbackBanner feedback={session.feedback} />

              {!session.feedback && (
                <div className="mt-6">
                  <p className="text-xs font-bold text-[#1c3257] uppercase tracking-wider mb-2">
                    ¿Cómo respondió?
                  </p>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'success', text: lessonData.challenge?.successFeedback || '¡Muy bien! Fundamentaste tu respuesta de forma correcta.' },
                        challengeCompleted: true
                      })}
                      className="bg-white hover:bg-[#eaf4e8] border border-[#badcb8] rounded-xl p-3.5 text-xs font-bold text-[#255e29] transition-all cursor-pointer"
                    >
                      Explicó correctamente
                    </button>
                    <button
                      type="button"
                      onClick={() => updateSession({
                        feedback: { kind: 'support', text: lessonData.challenge?.supportFeedback || 'Revisémoslo juntos paso a paso para identificar la clave del problema.' },
                        challengeCompleted: true
                      })}
                      className="bg-white hover:bg-[#fff0e4] border border-[#f5c49d] rounded-xl p-3.5 text-xs font-bold text-[#794112] transition-all cursor-pointer"
                    >
                      Necesita apoyo
                    </button>
                  </div>
                </div>
              )}

              {session.feedback && (
                <div className="flex justify-end mt-6">
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'strategy', feedback: null })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Ver estrategia para pensar</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}

          {/* 19. STAGE: STRATEGY */}
          {session.stage === 'strategy' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">
                {lessonData.strategy?.title || 'Cómo analizar una situación'}
              </h1>
              <PromptBox label="DILE">
                {lessonData.strategy?.dileIntro || 'Cuando analices una situación en esta lección, puedes seguir tres pasos clave: primero identifica los datos iniciales, luego aplica la regla correspondiente y finalmente comprueba tu resultado.'}
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'practiceSummary', summaryIdea: 0, feedback: null })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Recordemos lo aprendido</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 20. STAGE: PRACTICE SUMMARY (3 Ideas) */}
          {session.stage === 'practiceSummary' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Recordemos lo aprendido</h1>
              {session.summaryIdea === 0 && (
                <PromptBox label="DILE">
                  Antes de terminar, recordemos las tres ideas más importantes que aprendimos hoy.
                </PromptBox>
              )}

              <div className="space-y-3 mt-4">
                {lessonData.summaryIdeas.slice(0, session.summaryIdea).map(([title, text]) => (
                  <PromptBox key={title} label={`DILE · ${title}`} tone="teal">
                    {text}
                  </PromptBox>
                ))}
              </div>

              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                {session.summaryIdea < 3 ? (
                  <button
                    type="button"
                    onClick={() => updateSession({ summaryIdea: session.summaryIdea + 1 })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Mostrar idea {session.summaryIdea + 1}</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                ) : (
                  <button
                    type="button"
                    onClick={() => updateSession({ stage: 'miniquiz', quizVisible: false })}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>Continuar al miniquiz</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          )}

          {/* 21. STAGE: MINIQUIZ */}
          {session.stage === 'miniquiz' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Miniquiz de la clase</h1>
              {!session.quizVisible ? (
                <div>
                  <PromptBox label="DILE">
                    Para terminar, responderás un miniquiz con tres preguntas sobre lo que aprendimos hoy. Tendrás que responderlo en tu pantalla. Cuando lo envíes, revisaremos juntos tus resultados.
                  </PromptBox>
                  <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                    <button
                      type="button"
                      onClick={() => updateSession({ quizVisible: true })}
                      className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                    >
                      <span>Mostrar miniquiz</span>
                      <ArrowRight className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ) : (
                <div className="bg-white p-6 rounded-2xl border border-[#dce2e6] text-center">
                  <PrivateBox>
                    Permite que el estudiante responda sin ayuda. Cuando envíe el miniquiz recibirás los resultados. Se aprueba con al menos dos respuestas correctas.
                  </PrivateBox>
                  <div className="flex items-center justify-center gap-3 text-sm text-[#12a1a4] font-semibold mt-6 py-4 bg-[#f0fbfb] rounded-xl border border-[#d2f0f0]">
                    <span className="w-2.5 h-2.5 rounded-full bg-[#12a1a4] animate-ping" />
                    <span>El estudiante está respondiendo en su pantalla...</span>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* 22. STAGE: RESULTS */}
          {session.stage === 'results' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Resultado del miniquiz</h1>
              <div className="bg-white p-6 rounded-2xl border border-[#dce2e6] mb-4 text-center">
                <div className="text-3xl font-extrabold text-[#1c3257] mb-1">
                  {session.miniScore} / 3
                </div>
                <p className="text-sm font-bold text-[#12a1a4]">
                  {session.miniScore === 3
                    ? '¡Excelente trabajo!'
                    : session.miniScore >= 2
                    ? '¡Muy bien! Aprobaste la clase.'
                    : 'Sigamos aprendiendo'}
                </p>
              </div>

              <PromptBox label="DILE">
                {session.miniScore === 3
                  ? '¡Excelente trabajo! Respondiste correctamente las tres preguntas. Comprendiste muy bien lo que aprendimos hoy.'
                  : session.miniScore >= 2
                  ? '¡Muy bien! Aprobaste la clase. Revisaremos las respuestas para que todo quede claro.'
                  : 'Vamos a revisar las respuestas que necesitan apoyo y luego haremos una comprobación breve.'}
              </PromptBox>

              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'review', reviewIndex: 0 })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Recordemos las respuestas</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 23. STAGE: REVIEW */}
          {session.stage === 'review' && (() => {
            const currentQuestionIdx = session.reviewQueue[session.reviewIndex] ?? 0;
            const currentItem = lessonData.mini[currentQuestionIdx] ?? lessonData.mini[0];
            const isLast = session.reviewIndex >= session.reviewQueue.length - 1;

            const handleNext = () => {
              if (isLast) {
                updateSession({ stage: session.miniScore >= 2 ? 'closing' : 'recoveryIntro' });
              } else {
                updateSession({ reviewIndex: session.reviewIndex + 1 });
              }
            };

            return (
              <div>
                <h1 className="text-2xl font-bold text-[#1c3257] mb-4">
                  Revisemos la respuesta {session.reviewIndex + 1} de {session.reviewQueue.length}
                </h1>

                <div className="bg-white p-5 rounded-2xl border border-[#dce2e6] mb-4">
                  <span className="text-xs uppercase font-bold text-[#748093] block mb-1">Pregunta</span>
                  <p className="text-sm font-semibold text-[#1c3257] mb-3">{currentItem.q}</p>
                  <div className="flex flex-col sm:flex-row gap-2 sm:gap-6 text-xs pt-2 border-t border-[#f1f5f9]">
                    <span className="text-[#526177]">
                      Respondió: <b className="text-[#1c3257]">{session.miniAnswers[currentQuestionIdx] || '(sin responder)'}</b>
                    </span>
                    <strong className="text-[#255e29]">
                      Respuesta correcta: {currentItem.correct}
                    </strong>
                  </div>
                </div>

                <PromptBox label="DILE">
                  {currentItem.dileReview || currentItem.fixExplain}
                </PromptBox>

                {currentItem.dileReview && (
                  <div className="bg-[#f8fafc] border border-[#e2e8f0] rounded-2xl p-4 mt-3">
                    <span className="text-[10px] font-bold uppercase tracking-wider text-[#748093] block mb-1">
                      Explicación Pedagógica en Pantalla del Estudiante
                    </span>
                    <p className="text-xs text-[#334157] leading-relaxed">
                      {currentItem.fixExplain}
                    </p>
                  </div>
                )}

                <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                  <button
                    type="button"
                    onClick={handleNext}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>{isLast ? (session.miniScore >= 2 ? 'Ir al cierre' : 'Ir al refuerzo') : 'Siguiente respuesta'}</span>
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              </div>
            );
          })()}

          {/* 24. STAGE: RECOVERY INTRO */}
          {session.stage === 'recoveryIntro' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Refuerzo breve</h1>
              <PromptBox label="DILE">
                Revisaremos paso a paso las ideas que todavía necesitan un poco de práctica. Después harás una comprobación breve.
              </PromptBox>
              <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                <button
                  type="button"
                  onClick={() => updateSession({ stage: 'recovery', recoveryIndex: 0, recoveryVisible: false, recoveryAnswer: '' })}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Comenzar refuerzo</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}

          {/* 25. STAGE: RECOVERY */}
          {session.stage === 'recovery' && (() => {
            const recoveryItemIdx = session.recoveryItems[session.recoveryIndex] ?? 0;
            const item = lessonData.recovery[recoveryItemIdx] ?? lessonData.recovery[0];
            const answered = Boolean(session.recoveryAnswer);
            const isCorrect = session.recoveryAnswer === item.correct;
            const isLast = session.recoveryIndex >= session.recoveryItems.length - 1;

            const handleNext = () => {
              if (isLast) {
                updateSession({ stage: 'closing' });
              } else {
                updateSession({
                  recoveryIndex: session.recoveryIndex + 1,
                  recoveryVisible: false,
                  recoveryAnswer: ''
                });
              }
            };

            return (
              <div>
                <h1 className="text-2xl font-bold text-[#1c3257] mb-4">
                  Refuerzo {session.recoveryIndex + 1} de {session.recoveryItems.length}: {item.title}
                </h1>
                <PromptBox label="DILE">
                  {item.explain}
                </PromptBox>

                {!session.recoveryVisible ? (
                  <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                    <button
                      type="button"
                      onClick={() => updateSession({ recoveryVisible: true })}
                      className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                    >
                      <span>Mostrar comprobación</span>
                      <ArrowRight className="w-4 h-4" />
                    </button>
                  </div>
                ) : !answered ? (
                  <div className="flex items-center justify-center gap-3 text-sm text-[#12a1a4] font-semibold mt-6 py-4 bg-[#f0fbfb] rounded-xl border border-[#d2f0f0]">
                    <span className="w-2.5 h-2.5 rounded-full bg-[#12a1a4] animate-ping" />
                    <span>El estudiante está trabajando en su cuaderno...</span>
                  </div>
                ) : item.kind === 'open_response' || !item.options || item.options.length === 0 ? (
                  <div className="mt-6 space-y-4">
                    <div className="bg-[#f0fbfb] border border-[#b2e4e4] rounded-2xl p-4 text-xs sm:text-sm text-[#1c3257]">
                      <strong className="text-[#12a1a4] uppercase tracking-wider block mb-1 text-xs">Pauta privada del mentor (no visible para el estudiante):</strong>
                      <p className="font-semibold mb-2">{item.correctText}</p>
                      {item.fixText && (
                        <p className="text-xs text-[#526177]"><span className="font-bold">Apoyo pedagógico:</span> {item.fixText}</p>
                      )}
                    </div>

                    <div className="flex flex-col sm:flex-row items-center gap-3 pt-2">
                      <button
                        type="button"
                        onClick={() => {
                          updateSession(evaluateOpenRecoveryTask(true));
                          handleNext();
                        }}
                        className="w-full sm:w-auto bg-[#255e29] hover:bg-[#1e4b21] text-white font-bold px-6 py-3 rounded-xl text-sm transition-all shadow-md cursor-pointer flex items-center justify-center gap-2"
                      >
                        <span>✓ Cumple el criterio (Acierto)</span>
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          updateSession(evaluateOpenRecoveryTask(false));
                          handleNext();
                        }}
                        className="w-full sm:w-auto bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl text-sm transition-all shadow-md cursor-pointer flex items-center justify-center gap-2"
                      >
                        <span>{isLast ? 'Finalizar sesión (Requiere apoyo)' : 'Continuar con apoyo'}</span>
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="mt-6">
                    <PromptBox label="DILE" tone={isCorrect ? 'teal' : 'orange'}>
                      {isCorrect ? item.correctText : item.fixText}
                    </PromptBox>
                    <div className="flex justify-end mt-8 pt-4 border-t border-[#dce2e6]">
                      <button
                        type="button"
                        onClick={() => {
                          if (isCorrect) (session as any).recoveryPassed = true;
                          handleNext();
                        }}
                        className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                      >
                        <span>{isLast ? 'Finalizar refuerzo' : 'Siguiente refuerzo'}</span>
                        <ArrowRight className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })()}

          {/* 26. STAGE: CLOSING */}
          {session.stage === 'closing' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Terminamos por hoy</h1>
              <PromptBox label="DILE">
                {lessonData.closure?.congratulations || `¡Felicitaciones! Hoy completaste con éxito la clase "${lessonData.metadata.lessonTitle}". Has demostrado gran curiosidad y constancia en tu aprendizaje.`}
              </PromptBox>
              <PromptBox label="DILE" tone="teal">
                {lessonData.closure?.nextClassPreview || (lessonData.metadata.nextLessonTitle ? `En la próxima clase trabajaremos: "${lessonData.metadata.nextLessonTitle}".` : '¡Nos vemos en la próxima sesión!')}
              </PromptBox>

              {/* Registro de la sesión */}
              <div className="bg-white p-5 rounded-2xl border border-[#dce2e6] mt-6 flex items-start gap-3">
                <Info className="w-5 h-5 text-[#12a1a4] shrink-0 mt-0.5" />
                <div className="text-xs text-[#526177] leading-relaxed">
                  <strong className="text-[#1c3257] text-sm block mb-1">Registro de la sesión · Solo para ti</strong>
                  <p>
                    {session.supportCount === 0
                      ? 'El estudiante completó las actividades orales sin apoyo guiado.'
                      : `Se utilizaron apoyos guiados en ${session.supportCount} ${session.supportCount === 1 ? 'momento' : 'momentos'}.`}
                    {' '}
                    {session.reasoningIndependent
                      ? 'Explicó la comparación de contextos de manera autónoma.'
                      : 'Completó la comparación de contextos con acompañamiento.'}
                    {' '}
                    Resultado del miniquiz: {session.miniScore} de 3.
                  </p>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-8 pt-4 border-t border-[#dce2e6]">
                <div className="text-xs text-[#526177]">
                  {session.miniScore >= 2 ? (
                    <span className="text-[#255e29] font-bold">✓ Criterio de logro acreditado ({session.miniScore}/3 aciertos).</span>
                  ) : (
                    <span className="text-[#924814] font-semibold">⚠ Clase pendiente de consolidación: requiere al menos 2/3 aciertos tras reintento para acreditar logro.</span>
                  )}
                </div>
                <div className="flex flex-wrap items-center gap-3">
                  {session.miniScore < 2 && (
                    <button
                      type="button"
                      onClick={() => updateSession(retestMiniquiz(session))}
                      className="bg-white hover:bg-slate-50 border-2 border-[#badcb8] rounded-xl px-4 py-3 text-xs font-bold text-[#255e29] transition-all cursor-pointer flex items-center gap-2"
                    >
                      <span>↺ Reintentar comprobación (Miniquiz)</span>
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => {
                      if (lessonData?.metadata) {
                        const canonicalKey = getLessonCanonicalKey(
                          lessonData.metadata.grade,
                          lessonData.metadata.subject,
                          lessonData.metadata.oaCode,
                          lessonData.metadata.lessonNumber
                        );
                        finalizeLessonSession(session, canonicalKey, markLessonCompleted);
                      }
                      updateSession({ stage: 'completed' });
                    }}
                    className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-8 py-3.5 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                  >
                    <span>{canAccreditLesson(session) ? 'Finalizar y registrar clase lograda' : 'Finalizar sesión (sin acreditar logro)'}</span>
                    <Check className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* COMPLETED */}
          {session.stage === 'completed' && (
            <div className="text-center py-10 flex flex-col items-center justify-center min-h-[500px]">
              <div className="w-16 h-16 rounded-full bg-[#eaf4e8] text-[#255e29] flex items-center justify-center mb-4">
                <CheckCircle2 className="w-10 h-10" />
              </div>
              <h1 className="text-3xl font-extrabold text-[#1c3257] mb-2">
                ¡Clase {lessonData.metadata.lessonNumber} completada con éxito!
              </h1>
              <p className="text-sm text-[#526177] max-w-md mx-auto mb-8 leading-relaxed">
                Has finalizado la clase de {lessonData.metadata.subject} con tu estudiante. Los avances han quedado registrados.
              </p>
              <div className="flex flex-col sm:flex-row items-center justify-center gap-3">
                <button
                  type="button"
                  onClick={() => {
                    const targetMode = authSession?.role === 'student' ? 'student' : 'parent';
                    setViewMode(targetMode);
                  }}
                  className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-md transition-all cursor-pointer"
                >
                  <span>Volver al panel de lecciones</span>
                  <Home className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={() => resetSession()}
                  className="bg-white hover:bg-slate-50 text-[#1c3257] border border-slate-300 font-bold px-6 py-3 rounded-xl flex items-center gap-2 text-sm shadow-sm transition-all cursor-pointer"
                >
                  <span>Repetir esta clase</span>
                  <RotateCcw className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface AdultVideoPlayerProps {
  src: string;
  kind: 'hook' | 'formal';
  session: any;
  updateSession: (patch: any) => void;
}

const AdultVideoPlayer: React.FC<AdultVideoPlayerProps> = ({ src, kind, session, updateSession }) => {
  const ref = useRef<HTMLVideoElement>(null);
  const lastSharedSecond = useRef(-1);
  const [time, setTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    setHasError(false);
  }, [src]);

  const videoInfo = resolveVideoSource(src);
  const isIframe = videoInfo.isEmbed && Boolean(videoInfo.embedUrl);

  useEffect(() => {
    if (isIframe) return;
    const v = ref.current;
    if (!v || session.video.kind !== kind) return;
    if (Math.abs(v.currentTime - session.video.seek) > 1.2) {
      v.currentTime = session.video.seek;
    }
    if (session.video.playing) {
      v.play().catch(() => undefined);
    } else {
      v.pause();
    }
  }, [kind, session.video, isIframe]);

  const command = (playing: boolean, seek = ref.current?.currentTime ?? 0) => {
    updateSession({
      video: { kind, playing, seek, command: session.video.command + 1 }
    });
  };

  const handleSkipOrComplete = () => {
    if (kind === 'hook') {
      updateSession({
        hookStarted: true,
        hookEnded: true,
        stage: 'conversationIntro',
        video: { ...session.video, playing: false }
      });
    } else {
      updateSession({
        formalStarted: true,
        formalEnded: true,
        stage: 'postIntro',
        video: { ...session.video, playing: false }
      });
    }
  };

  if (!src || src.trim() === '' || !videoInfo.isValid) {
    return (
      <div className="bg-white p-6 rounded-2xl border border-[#dce2e6] mt-4 text-center">
        <div className="w-14 h-14 rounded-full bg-[#f0f4f8] text-[#1c3257] flex items-center justify-center mx-auto mb-3 border border-[#dce2e6]">
          <Play className="w-6 h-6 text-[#12a1a4]" />
        </div>
        <h3 className="text-base font-bold text-[#1c3257] mb-1">
          Cápsula audiovisual complementaria
        </h3>
        <p className="text-xs text-[#526177] max-w-md mx-auto mb-5 leading-relaxed">
          Esta lección no incluye video pregrabado. Puedes avanzar directamente utilizando las preguntas guiadas y el material en pantalla.
        </p>
        <button
          type="button"
          onClick={handleSkipOrComplete}
          className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-6 py-2.5 rounded-xl text-xs flex items-center gap-2 mx-auto transition-all cursor-pointer shadow-sm"
        >
          <span>Continuar a la siguiente etapa</span>
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    );
  }
  if (hasError) {
    return (
      <div className="bg-amber-50/90 border border-amber-300 rounded-2xl p-6 mt-4 text-center shadow-sm">
        <div className="w-12 h-12 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center mx-auto mb-3">
          <AlertTriangle className="w-6 h-6" />
        </div>
        <h3 className="text-base font-bold text-amber-900 mb-1">
          Video no disponible
        </h3>
        <p className="text-xs text-amber-700 max-w-md mx-auto mb-4 leading-relaxed">
          No fue posible reproducir el archivo de video (posible recurso no encontrado o error de red). Puedes continuar con las actividades y preguntas guiadas sin problemas.
        </p>
        <div className="flex flex-wrap items-center justify-center gap-3">
          <button
            type="button"
            onClick={() => {
              setHasError(false);
              if (ref.current) {
                ref.current.load();
              }
            }}
            className="bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 font-bold px-4 py-2 rounded-xl text-xs flex items-center gap-1.5 transition-all cursor-pointer"
          >
            <RotateCcw className="w-3.5 h-3.5" />
            <span>Reintentar</span>
          </button>
          <button
            type="button"
            onClick={handleSkipOrComplete}
            className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-5 py-2 rounded-xl text-xs flex items-center gap-2 transition-all cursor-pointer shadow-sm"
          >
            <span>Continuar a la siguiente etapa</span>
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white p-5 rounded-2xl border border-[#dce2e6] mt-4">
      <div className="text-xs text-[#748093] bg-[#f8fafc] p-2.5 rounded-xl border border-[#e2e8f0] mb-4">
        {isIframe
          ? 'Video en modalidad de transmisión externa. Puedes visualizarlo aquí y marcar como visto al terminar.'
          : 'Este video está silenciado aquí para evitar audio duplicado. Los controles también actúan sobre la pantalla del estudiante.'}
      </div>

      <div className="relative rounded-xl overflow-hidden bg-black aspect-video max-h-[360px] mx-auto flex items-center justify-center">
        {isIframe && videoInfo.embedUrl ? (
          <iframe
            src={videoInfo.embedUrl}
            className="w-full h-full border-0"
            allow="accelerometer; gyroscope; autoplay; encrypted-media; picture-in-picture;"
            allowFullScreen
            title="Video embebido"
          />
        ) : (
          <video
            ref={ref}
            src={videoInfo.cleanUrl}
            muted
            playsInline
            preload="auto"
            className="w-full h-full object-contain"
            onError={(e) => {
              console.warn('Error al reproducir video en vista de adulto:', e);
              setHasError(true);
            }}
            onTimeUpdate={(e) => {
              const current = e.currentTarget.currentTime;
              setTime(current);
              const second = Math.floor(current);
              if (session.video.playing && second !== lastSharedSecond.current) {
                lastSharedSecond.current = second;
                updateSession({
                  video: { ...session.video, kind, seek: current }
                });
              }
            }}
            onLoadedMetadata={(e) => setDuration(e.currentTarget.duration)}
            onCanPlay={() => {
              if (session.video.playing) ref.current?.play().catch(() => undefined);
            }}
            onEnded={() => {
              updateSession(
                kind === 'hook'
                  ? {
                      hookEnded: true,
                      video: { ...session.video, playing: false, seek: ref.current?.duration ?? session.video.seek }
                    }
                  : {
                      formalEnded: true,
                      video: { ...session.video, playing: false, seek: ref.current?.duration ?? session.video.seek }
                    }
              );
            }}
          />
        )}
      </div>

      {!isIframe ? (
        <div className="flex items-center justify-between gap-3 mt-4 pt-3 border-t border-[#f1f5f9]">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => command(!session.video.playing)}
              className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold p-2.5 rounded-xl flex items-center justify-center cursor-pointer transition-all"
              title={session.video.playing ? 'Pausar' : 'Continuar'}
            >
              {session.video.playing ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 fill-white" />}
            </button>
            <button
              type="button"
              onClick={() => command(false, Math.max(0, (ref.current?.currentTime ?? 0) - 10))}
              className="bg-white hover:bg-[#f8fafc] text-[#1c3257] border border-[#dce2e6] font-bold px-3 py-2 rounded-xl text-xs flex items-center gap-1 cursor-pointer transition-all"
            >
              <Rewind className="w-3.5 h-3.5" /> 10 s
            </button>
            <button
              type="button"
              onClick={() => command(false, Math.min(duration, (ref.current?.currentTime ?? 0) + 10))}
              className="bg-white hover:bg-[#f8fafc] text-[#1c3257] border border-[#dce2e6] font-bold px-3 py-2 rounded-xl text-xs flex items-center gap-1 cursor-pointer transition-all"
            >
              10 s <FastForward className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={() => command(false, 0)}
              className="bg-white hover:bg-[#f8fafc] text-[#1c3257] border border-[#dce2e6] font-bold p-2 rounded-xl text-xs flex items-center justify-center cursor-pointer transition-all"
              title="Reiniciar video"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          </div>

          <div className="flex-1 flex items-center gap-3 max-w-xs">
            <input
              type="range"
              min={0}
              max={duration || 0}
              step={0.1}
              value={Math.min(time, duration || 0)}
              onChange={(e) => command(false, Number(e.target.value))}
              className="w-full h-1.5 bg-[#e2e8f0] rounded-lg appearance-none cursor-pointer accent-[#12a1a4]"
            />
            <span className="text-xs text-[#748093] font-mono shrink-0">
              {formatTime(time)} / {formatTime(duration)}
            </span>
          </div>
        </div>
      ) : (
        <div className="flex items-center justify-end gap-3 mt-4 pt-3 border-t border-[#f1f5f9]">
          <button
            type="button"
            onClick={handleSkipOrComplete}
            className="bg-[#EE751C] hover:bg-[#D96512] text-white font-bold px-5 py-2 rounded-xl text-xs flex items-center gap-2 transition-all cursor-pointer shadow-sm"
          >
            <span>Marcar video como visto y continuar</span>
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useLessonSync } from '../../../context/LessonSyncContext';
import { submitStudentRecoveryAnswer } from '../../../lib/lesson-session';

export const StudentRecoveryView: React.FC = () => {
  const { session, lessonData, updateSession } = useLessonSync();

  const itemIdx = session.recoveryItems[session.recoveryIndex] ?? 0;
  const item = lessonData.recovery[itemIdx] ?? lessonData.recovery[0];
  const totalRecovery = session.recoveryItems.length || 1;
  const isOpenTask = item.kind === 'open_response' || !item.options || item.options.length === 0;
  const answered = Boolean(session.recoveryAnswer);
  const isCorrect = isOpenTask ? session.recoveryAnswer === 'completed_open_task' : session.recoveryAnswer === item.correct;

  return (
    <div className="max-w-xl mx-auto p-6 animate-fadeIn">
      <div className="text-center mb-6">
        <span className="text-[#12a1a4] font-bold text-xs uppercase tracking-widest block mb-1">
          Refuerzo {session.recoveryIndex + 1} de {totalRecovery}
        </span>
        <h1 className="text-2xl font-extrabold text-[#1c3257]">{item.title}</h1>
      </div>

      <div className="bg-white border border-[#dce2e6] rounded-2xl p-5 mb-6 text-sm text-[#334157] leading-relaxed shadow-sm">
        {item.explain}
      </div>

      {session.recoveryVisible && !answered && (
        <div className="bg-[#e9f8f8] border border-[#12a1a4] rounded-2xl p-5 shadow-sm animate-fadeIn">
          {item.resource && (
            <div className="bg-white border border-[#b2e4e4] rounded-xl p-3.5 mb-4 text-xs sm:text-sm text-[#1c3257] leading-relaxed">
              <strong className="text-[#12a1a4] block mb-1 uppercase tracking-wider text-[11px]">Recurso de apoyo:</strong>
              {item.resource}
            </div>
          )}
          <h2 className="text-sm font-bold text-[#1c3257] mb-4">
            {item.q}
          </h2>

          {isOpenTask ? (
            <div className="flex flex-col gap-3">
              <p className="text-xs text-[#526177] italic">
                Resuelve la tarea en tu cuaderno físico. Cuando termines, presiona el botón para avisarle a tu mentor.
              </p>
              <button
                type="button"
                onClick={() => updateSession(submitStudentRecoveryAnswer('completed_open_task'))}
                className="w-full bg-[#12a1a4] hover:bg-[#0e8082] text-white font-bold p-3.5 rounded-xl text-sm transition-all shadow-sm cursor-pointer flex items-center justify-center gap-2"
              >
                <span>✓ Listo, ya resolví la tarea en mi cuaderno</span>
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {(item.options || []).map((opt) => (
                <button
                  key={opt}
                  type="button"
                  onClick={() => updateSession(submitStudentRecoveryAnswer(opt))}
                  className="bg-white hover:bg-[#12a1a4] text-[#1c3257] hover:text-white font-bold p-3.5 rounded-xl border border-[#bac5d0] hover:border-[#12a1a4] text-sm transition-all shadow-sm cursor-pointer"
                >
                  {opt}
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {answered && (
        <div
          className={`rounded-2xl p-5 shadow-sm animate-fadeIn border ${
            isCorrect
              ? 'bg-[#eaf4e8] border-[#badcb8] text-[#255e29]'
              : 'bg-[#fff5ee] border-[#f5c49d] text-[#924814]'
          }`}
        >
          <strong className="text-sm font-bold block mb-1">
            {isOpenTask ? '¡Excelente trabajo en tu cuaderno!' : (isCorrect ? '¡Muy bien!' : 'Revisemos la respuesta')}
          </strong>
          <p className="text-xs sm:text-sm leading-relaxed">
            {isOpenTask ? (item.correctText || item.explain || 'Tu mentor revisará la fundamentación en tu cuaderno.') : (isCorrect ? item.correctText : item.fixText)}
          </p>
        </div>
      )}

      <p className="text-center text-xs text-[#748093] font-semibold mt-6">
        Escucha a tu mentor para continuar con la sesión.
      </p>
    </div>
  );
};

import React, { useRef, useState, useEffect, useMemo } from 'react';
import { useLessonSync } from '../../../context/LessonSyncContext';
import { useApp } from '../../../context/AppContext';
import { StudentHeader } from './StudentHeader';
import { StudentDisciplineGraphic } from './StudentDisciplineGraphic';
import { StudentMiniquizView } from './StudentMiniquizView';
import { StudentQuizReviewView } from './StudentQuizReviewView';
import { StudentRecoveryView } from './StudentRecoveryView';
import { ConfettiEffect } from './ConfettiEffect';
import { SupportHintCard } from './SupportHintCard';
import { OptionalAudioPlayer } from '../common/OptionalAudioPlayer';
import { StudentReadingResourceCard } from './StudentReadingResourceCard';
import { getSubjectTheme } from '../../../lib/subject-theme';
import { resolveVideoSource } from '../../../lib/video-utils';
import { getLessonCanonicalKey } from '../../../lib/lesson-repository';
import { canAccreditLesson } from '../../../lib/lesson-session';
import {
  Sparkles,
  Check,
  CircleHelp,
  ArrowRight,
  Play,
  Home,
  RotateCcw,
  AlertCircle,
  Send,
  MessageSquare,
  BookOpen
} from 'lucide-react';

function isAmbientActiveStage(
  stage: string,
  hookStarted: boolean,
  hookEnded: boolean,
  formalStarted: boolean,
  formalEnded: boolean
): boolean {
  if (['cover', 'prep'].includes(stage)) return true;
  if (['conversationIntro', 'preQuestions', 'postIntro', 'postQuestions', 'summary'].includes(stage)) return true;
  if (stage === 'hook') return !hookStarted || hookEnded;
  if (stage === 'formalization') return !formalStarted || formalEnded;
  return false;
}

interface StudentAnswerSectionProps {
  questionKey: string;
  feedback: { kind: 'success' | 'support' | 'reveal' | 'info'; text: string } | null;
  studentReveal: string;
  onSubmitAnswer: (key: string, ans: string) => void;
  savedAnswer?: string;
  hintMessage?: string;
}

const StudentAnswerSection: React.FC<StudentAnswerSectionProps> = ({
  questionKey,
  feedback,
  studentReveal,
  onSubmitAnswer,
  savedAnswer = '',
  hintMessage = 'Presta atención a la pista que te dará tu mentor.'
}) => {
  const [text, setText] = useState(savedAnswer);
  const [isEditing, setIsEditing] = useState(!savedAnswer);

  useEffect(() => {
    setText(savedAnswer);
    if (!savedAnswer) {
      setIsEditing(true);
    }
  }, [savedAnswer, questionKey]);

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (text.trim()) {
      onSubmitAnswer(questionKey, text.trim());
      setIsEditing(false);
    }
  };

  // No mostrar la solución modelo antes de que el estudiante responda
  const studentHasAnswered = Boolean(savedAnswer && savedAnswer.trim().length > 0);
  const isResolved = (feedback?.kind === 'success' || feedback?.kind === 'reveal') && studentHasAnswered;

  return (
    <div className="mt-4 text-left">
      <SupportHintCard
        visible={feedback?.kind === 'support'}
        message={hintMessage}
      />

      {isResolved && (
        <div className="bg-emerald-50 border border-emerald-200 text-emerald-800 p-4 rounded-2xl text-sm font-bold flex items-center justify-center gap-2 shadow-xs animate-fadeIn my-3">
          <Sparkles className="w-5 h-5 text-emerald-600 shrink-0" />
          <span>{studentReveal}</span>
        </div>
      )}

      {/* Tarjeta de Respuesta Escrita del Estudiante (Una sola respuesta registrada por caso) */}
      <div className="bg-slate-50 border border-slate-200/90 rounded-2xl p-4 transition-all mt-3">
        <div className="flex items-center justify-between mb-2">
          <span className="text-[11px] font-extrabold uppercase tracking-wider text-[#1C3257] flex items-center gap-1.5">
            <Send className="w-3.5 h-3.5 text-[#EE751C]" />
            Tu respuesta para tu mentor:
          </span>
          {savedAnswer && !isEditing ? (
            <span className="text-[10px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full flex items-center gap-1">
              <Check className="w-3 h-3" />
              Respuesta registrada
            </span>
          ) : (
            <span className="text-[10px] font-bold text-slate-400">
              {isResolved ? 'Completada' : 'Escribe y envía una sola respuesta'}
            </span>
          )}
        </div>

        {isEditing && !isResolved ? (
          <form onSubmit={handleSubmit} className="space-y-2">
            <textarea
              rows={2}
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Escribe tu respuesta aquí para tu mentor..."
              className="w-full text-xs sm:text-sm font-semibold text-[#1C3257] bg-white border border-slate-300 rounded-xl p-3 focus:outline-none focus:ring-2 focus:ring-[#EE751C]/40 focus:border-[#EE751C] transition-all resize-none shadow-2xs"
              autoFocus
            />
            <div className="flex items-center justify-between">
              <span className="text-[10px] text-slate-400">
                Tu mentor revisará tu respuesta.
              </span>
              <button
                type="submit"
                disabled={!text.trim()}
                className="bg-[#EE751C] hover:bg-[#D96512] disabled:opacity-40 disabled:hover:bg-[#EE751C] text-white font-extrabold text-xs px-4 py-2 rounded-xl shadow-xs transition-all flex items-center gap-1.5 cursor-pointer disabled:cursor-not-allowed"
              >
                <span>Enviar respuesta</span>
                <Send className="w-3.5 h-3.5" />
              </button>
            </div>
          </form>
        ) : (
          <div>
            <div className="p-3 bg-white border border-slate-200 rounded-xl text-xs sm:text-sm font-bold text-[#1C3257] whitespace-pre-wrap">
              {savedAnswer || text || '(Sin respuesta escrita)'}
            </div>
            {!isResolved && (
              <div className="flex items-center justify-between mt-2.5">
                <span className="text-[10px] text-amber-700 font-semibold flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-ping" />
                  Tu mentor está revisando tu respuesta...
                </span>
                {feedback?.kind === 'support' && (
                  <button
                    type="button"
                    onClick={() => setIsEditing(true)}
                    className="text-[11px] font-bold text-[#12A1A4] hover:underline cursor-pointer"
                  >
                    Ajustar con la pista
                  </button>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export const StudentLessonView: React.FC = () => {
  const { session, lessonData, setStage, peerRoleConnected, submitStudentAnswer, resetSession } = useLessonSync();
  const { setViewMode, setActiveSynchronizedLesson, markLessonCompleted, authSession } = useApp();
  const theme = getSubjectTheme(lessonData.metadata.subject);
  const audioRef = useRef<HTMLAudioElement>(null);
  const [soundOn, setSoundOn] = useState(true);
  const [blocked, setBlocked] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  const [showReadingConsult, setShowReadingConsult] = useState(false);
  const [consultParagraph, setConsultParagraph] = useState<number | undefined>(undefined);
  const prevFeedbackRef = useRef<string | null>(null);

  useEffect(() => {
    if (session.stage === 'completed' && canAccreditLesson(session) && lessonData?.metadata) {
      const canonicalKey = getLessonCanonicalKey(
        lessonData.metadata.grade,
        lessonData.metadata.subject,
        lessonData.metadata.oaCode,
        lessonData.metadata.lessonNumber
      );
      markLessonCompleted(canonicalKey);
    }
  }, [session.stage, session.miniScore, lessonData?.metadata, markLessonCompleted]);

  // Trigger confetti on success/reveal feedback transitions
  useEffect(() => {
    const currentKind = session.feedback?.kind || null;
    if (
      (currentKind === 'success' || currentKind === 'reveal') &&
      prevFeedbackRef.current !== currentKind
    ) {
      setShowConfetti(true);
      prevFeedbackRef.current = currentKind;
      const timer = setTimeout(() => setShowConfetti(false), 3000);
      return () => clearTimeout(timer);
    }
    // Always update ref so null->success->null->success triggers correctly
    prevFeedbackRef.current = currentKind;
  }, [session.feedback?.kind]);

  // Reset feedback tracking ref when moving between stages or questions
  useEffect(() => {
    prevFeedbackRef.current = null;
  }, [
    session.stage,
    session.conversationIndex,
    session.postIndex,
    session.practiceIndex,
    session.reviewIndex,
    session.recoveryIndex
  ]);

  const isAmbientActive = isAmbientActiveStage(
    session.stage,
    session.hookStarted,
    session.hookEnded,
    session.formalStarted,
    session.formalEnded
  );

  useEffect(() => {
    const player = audioRef.current;
    if (!player) return;
    player.volume = 0.12;
    if (isAmbientActive && soundOn && lessonData.ambientAudioSrc) {
      player
        .play()
        .then(() => setBlocked(false))
        .catch(() => setBlocked(true));
    } else {
      player.pause();
      if (!isAmbientActive) player.currentTime = 0;
    }
  }, [isAmbientActive, soundOn, lessonData.ambientAudioSrc]);

  const toggleSound = () => {
    if (soundOn && !blocked) {
      setSoundOn(false);
